<template>
  <Teleport to="body">
	<div v-if="show" ref="scrollEl" class="player" :class="[isDark ? 'player--dark' : 'player--light', `player--${storyDocument.settings.density}`, performanceEditMode ? `player--tool-${performanceTool}` : '', screenEffectClass, persistentEffectClasses, { 'player--performance-edit': performanceEditMode, 'player--source-open': sourceActive, 'player--playback-only': playbackOnly }]" :style="playerStyle" @pointerdown.capture="rememberPointerOrigin" @click="onPlayerRootClick" @scroll.passive="schedulePlayerStickyAvatar">
      <header @click.stop>
        <button @click="sourceActive ? $emit('raw') : playbackOnly ? $emit('close') : started ? stopPlayback() : $emit('close')">{{ sourceActive ? '← 返回演出编辑' : '← 返回' }}</button>
        <div class="player-title">
          <input v-if="performanceEditMode" v-model="titleDraft" maxlength="120" aria-label="故事名" @change="saveTitle" @keydown.enter.prevent="saveTitle" />
          <strong v-else>{{ storyDocument.title }}</strong>
          <small v-if="performanceEditMode">演出编辑 · 点击消息设置编排</small>
          <small v-else-if="recording">录制中 · 点击画布推进</small>
          <small v-else>{{ started ? `${visibleCount} / ${playbackMessages.length}` : `${playbackMessages.length} 条消息` }}</small>
        </div>
        <div class="player-header-actions">
		  <div v-if="!started && !playbackOnly" class="player-download"><button title="下载与导出" aria-label="下载与导出" :aria-expanded="playerDownloadOpen" @click="playerDownloadOpen=!playerDownloadOpen"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m0 0 4-4m-4 4-4-4M5 20h14"/></svg></button><Transition name="settings-pop"><nav v-if="playerDownloadOpen"><button class="download-item download-item--ssp" @click="playerDownloadOpen=false;$emit('download')">SSP 工程包<small>Ctrl+S</small></button><button class="download-item download-item--legacy" @click="playerDownloadOpen=false;$emit('legacy-text')">传统日志 TXT<small>经典版可导入</small></button><button class="download-item download-item--html" @click="playerDownloadOpen=false;$emit('html')">内嵌 HTML</button><button class="download-item download-item--word" @click="playerDownloadOpen=false;$emit('word')">传统 Word</button><button class="download-item download-item--image" @click="playerDownloadOpen=false;imageExportOpen=true">预览长图</button></nav></Transition></div>
          <button v-if="!started && !playbackOnly" :class="{ active: performanceEditMode }" @click="togglePerformanceEdit">演出编辑</button>
          <button v-if="!started && performanceEditMode && !playbackOnly" :class="{ active: performanceToolsOpen }" @click="performanceToolsOpen=!performanceToolsOpen">编排工具</button>
          <button v-if="!started && !playbackOnly" title="打开故事语言源码编辑" @click="$emit('raw')">源码</button>
          <button v-if="!started && !playbackOnly" class="record" @click="startRecording">录制演出</button>
          <template v-if="recording"><button @click="toggleRecordingPause">{{ recordingPaused ? '继续录制' : '暂停录制' }}</button><button class="primary" @click="finishRecording(true)">退出并保存</button><button class="danger-solid" @click="finishRecording(false)">退出不保存</button></template>
          <button v-else-if="!playbackOnly || started" class="primary" @click="headerAction">{{ finished ? '重新演出' : !started ? '开始演出' : paused ? '继续演出' : '暂停演出' }}</button>
          <button v-if="started&&!recording" class="danger-solid" @click="stopPlayback">关闭演出</button>
        </div>
	  </header>
	  <section v-if="performanceEditMode && performanceToolsOpen" class="performance-tools" @click.stop>
		<nav><button :class="{active:performanceTool==='single'}" @click="performanceTool='single'">单条编辑</button><button :class="{active:performanceTool==='preview'}" @click="performanceTool='preview'">效果预览</button><button :class="{active:performanceTool==='brush'}" @click="performanceTool='brush'">特效笔刷</button><button :class="{active:performanceTool==='erase-one'}" @click="performanceTool='erase-one'">单条橡皮</button><button :class="{active:performanceTool==='multi'}" @click="performanceTool='multi'">多选批量</button><button :class="{active:performanceTool==='range'}" @click="performanceTool='range'">持续区间</button><button :class="{active:performanceTool==='erase-range'}" @click="performanceTool='erase-range'">区间橡皮</button></nav>
		<div v-if="performanceTool==='single'" class="tool-help">点击任一消息，设置该条的流式、文字动画、单次屏幕效果和停留时间。</div>
		<div v-else-if="performanceTool==='preview'" class="tool-help">点击任一消息，只预览该条的文字与屏幕效果，不会修改编排。</div>
		<div v-else-if="performanceTool==='brush'" class="brush-performance-wrap"><div class="brush-performance-tools"><div class="brush-effect-summary"><span><small>文字</small><b>{{ brushTokenAnimation==='inherit'?'跟随全局':tokenAnimationLabel(brushTokenAnimation) }}</b></span><span><small>屏幕</small><b>{{ brushScreenEffect==='none'?'关闭':`${screenEffectLabel(brushScreenEffect)} · ${effectColorLabel(brushEffectColor)}` }}</b></span><span><small>头像互动</small><b>{{ brushInteractionEffect==='none'?'关闭':`${interactionEffectLabel(brushInteractionEffect)} · ${brushInteractionTarget?.name||'未选目标'}` }}</b></span></div><label class="brush-overlay-switch"><span>叠加</span><n-switch v-model:value="brushOverlay" /></label><button type="button" class="primary" :aria-expanded="brushPickerOpen" @click="brushPickerOpen=true">选择特效</button><span>{{ brushOverlay?'点击消息追加一段，最多 5 段':'点击消息覆盖原有特效' }}</span></div></div>
		<div v-else-if="performanceTool==='erase-one'" class="tool-help">点击消息清除该条的文字、屏幕、头像互动与媒体编排；不会删除流式节奏或停留时间。</div>
		<div v-else-if="performanceTool==='multi'" class="batch-performance-tools"><span>已选 {{ performanceSelection.size }} 条</span><n-select v-model:value="batchStreamMode" :options="batchStreamOptions" /><n-select v-model:value="batchTokenAnimation" :options="batchTokenAnimationOptions" /><n-select v-model:value="batchScreenEffect" :options="batchScreenEffectOptions" /><template v-if="batchScreenEffect!=='unchanged'&&batchScreenEffect!=='none'"><div class="effect-palette effect-palette--compact" aria-label="批量特效颜色"><button v-for="color in effectColorOptions" :key="color.value" type="button" :class="{active:batchScreenEffectColor===color.value}" :style="{'--swatch':color.swatch||color.hex}" :title="color.label" :aria-label="color.label" @click="batchScreenEffectColor=color.value"><i></i></button></div><strong class="effect-palette-current">{{ effectColorLabel(batchScreenEffectColor) }}</strong><button class="effect-preview-button" type="button" @click="previewScreenEffect(batchScreenEffect,batchScreenEffectColor)">▶ 预览</button></template><button :disabled="!performanceSelection.size" class="primary" @click="applyBatchPerformance">应用</button><button @click="performanceSelection.clear()">清空</button></div>
		<div v-else-if="performanceTool==='range'" class="range-performance-tools"><button class="primary" type="button" @click="rangePickerOpen=true">选择区间屏幕特效</button><strong>{{ persistentEffectLabel(rangeEffect) }} · {{ effectColorLabel(rangeEffectColor) }}</strong><span v-if="rangeStartId" class="range-start-notice">已选择起始消息：{{ rangeStartSummary }}。再点一次可取消，点击另一条作为终点。</span><span v-else>先点击起始消息，再点击结束消息；完整区间才会落下标记。</span><button v-if="rangeStartId" @click="rangeStartId=''">取消起点</button><div v-if="storyDocument.effectTracks.length" class="effect-track-list"><button v-for="track in storyDocument.effectTracks" :key="track.id" :title="'删除 '+persistentEffectLabel(track.effect)" @click="removeEffectTrack(track.id)"><i :style="{'--track-color':effectColorValue(track.color)}"></i>{{ persistentEffectLabel(track.effect) }} ×</button></div></div>
		<div v-else class="tool-help">点击持续效果覆盖范围内的任一消息，删除经过该处的持续轨道。</div>
	  </section>
	  <Teleport to="body"><Transition name="performance-pop"><div v-if="brushPickerOpen" class="performance-modal effect-brush-modal" @click.self="brushPickerOpen=false"><section class="effect-brush-dialog" role="dialog" aria-modal="true" aria-label="特效笔刷设置">
		<header><div><strong>特效笔刷</strong><small>文字、屏幕与头像互动可以作为一套组合同时应用</small></div><button type="button" class="modal-close" aria-label="关闭特效笔刷" @click="brushPickerOpen=false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18" /></svg></button></header>
		<div class="effect-brush-body">
		  <nav class="effect-brush-switches" aria-label="笔刷包含的特效类型">
			<div class="effect-brush-switch-card" :class="{active:activeBrushSection==='text',enabled:brushTokenAnimation!=='inherit'}"><button type="button" @click="selectBrushSection('text')"><strong>文字特效</strong><small>{{ brushTokenAnimation === 'inherit' ? '跟随全局' : tokenAnimationLabel(brushTokenAnimation) }}</small></button><n-switch :value="brushTokenAnimation!=='inherit'" aria-label="启用文字特效" @update:value="toggleBrushText" /></div>
			<div class="effect-brush-switch-card" :class="{active:activeBrushSection==='screen',enabled:brushScreenEffect!=='none'}"><button type="button" @click="selectBrushSection('screen')"><strong>屏幕特效</strong><small>{{ brushScreenEffect === 'none' ? '无屏幕效果' : screenEffectLabel(brushScreenEffect) }}</small></button><n-switch :value="brushScreenEffect!=='none'" aria-label="启用屏幕特效" @update:value="toggleBrushScreen" /></div>
			<div class="effect-brush-switch-card" :class="{active:activeBrushSection==='interaction',enabled:brushInteractionEffect!=='none'}"><button type="button" @click="selectBrushSection('interaction')"><strong>头像互动</strong><small>{{ brushInteractionEffect === 'none' ? '无头像互动' : interactionEffectLabel(brushInteractionEffect) }}</small></button><n-switch :value="brushInteractionEffect!=='none'" aria-label="启用头像互动" @update:value="toggleBrushInteraction" /></div>
		  </nav>
		  <Transition name="settings-pop" mode="out-in">
			<section v-if="activeBrushSection==='text' && brushTokenAnimation!=='inherit'" key="text" class="effect-brush-detail">
			  <header><div><strong>文字特效</strong><small>选择本条消息中文字出现的方式</small></div></header>
			  <StoryEffectPicker show-text :text-effect="brushTokenAnimation" @text="setBrushTokenAnimation" />
			</section>
			<section v-else-if="activeBrushSection==='screen' && brushScreenEffect!=='none'" key="screen" class="effect-brush-detail">
			  <header><div><strong>屏幕特效</strong><small>动画、预制颜色和播放参数会作为一套应用</small></div></header>
			  <StoryEffectPicker show-screen show-parameters :screen-effect="brushScreenEffect" :color="brushEffectColor" :duration-ms="brushEffectDurationMs" :speed-percent="brushEffectSpeedPercent" :repeat="brushEffectRepeat" @screen="setBrushScreenEffect" @color="setBrushEffectColor" @duration="setBrushEffectDuration" @speed="setBrushEffectSpeed" @repeat="setBrushEffectRepeat" />
			</section>
			<section v-else-if="activeBrushSection==='interaction' && brushInteractionEffect!=='none'" key="interaction" class="effect-brush-detail">
			  <header><div><strong>头像互动</strong><small>目标和互动动作一起保存在本卡片内</small></div></header>
			  <label class="brush-interaction-target"><span>互动目标</span><n-select v-model:value="brushInteractionTargetId" :options="brushInteractionTargetOptions" placeholder="无目标" /></label>
			  <StoryEffectPicker show-interaction :interaction-effect="brushInteractionEffect" :interaction-reaction="brushInteractionReaction" :interaction-emoji="brushInteractionEmoji" :interaction-color="brushInteractionColor" :interaction-speed-percent="brushInteractionSpeedPercent" source-name="发送者" :target-name="brushInteractionTarget?.name || ''" :target-avatar="avatar(brushInteractionTarget)" @interaction="setBrushInteractionEffect" @reaction="brushInteractionReaction=$event" @emoji="brushInteractionEmoji=$event" @interaction-color="brushInteractionColor=$event" @interaction-speed="brushInteractionSpeedPercent=$event" />
			</section>
			<section v-else key="empty" class="effect-brush-empty"><strong>选择要配置的特效</strong><span>打开上方开关后显示详情；三类效果可以同时组合。</span></section>
		  </Transition>
		</div>
		<footer><label class="brush-overlay-switch"><span>叠加</span><n-switch v-model:value="brushOverlay" /></label><span>{{ brushOverlay?'保留已有特效并追加当前组合，单条最多 5 段。':'当前组合会覆盖消息已有的单次特效。' }}</span><button type="button" class="primary" @click="brushPickerOpen=false">完成</button></footer>
	  </section></div></Transition></Teleport>
	  <Teleport to="body"><Transition name="performance-pop"><div v-if="rangePickerOpen" class="performance-modal range-effect-modal" @click.self="rangePickerOpen=false"><section class="effect-brush-dialog range-effect-dialog" role="dialog" aria-modal="true" aria-label="区间屏幕特效"><header><div><strong>区间屏幕特效</strong><small>只配置持续覆盖画布的屏幕效果，选完后依次点起点与终点。</small></div><button type="button" class="modal-close" aria-label="关闭" @click="rangePickerOpen=false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18" /></svg></button></header><StoryEffectPicker show-persistent :persistent-effect="rangeEffect" :color="rangeEffectColor" :persistent-intensity="rangeEffectIntensity" :persistent-opacity="rangeEffectOpacity" :persistent-speed="rangeEffectSpeed" @persistent="setRangeEffect" @color="setRangeEffectColor" @persistent-intensity="rangeEffectIntensity=$event" @persistent-opacity="rangeEffectOpacity=$event" @persistent-speed="rangeEffectSpeed=$event" /><footer><span>雨水、血迹等模板也支持强度、透明度和速度调整。</span><button type="button" class="primary" @click="rangePickerOpen=false">完成</button></footer></section></div></Transition></Teleport>
		  <Transition name="sticky-avatar">
		    <div v-if="stickyCharacter" :key="stickyCharacter.id" class="sticky-avatar" :class="characterStateClass(stickyCharacter.id,stickyMessageIndex)" :style="stickyAvatarStyle"><span class="player-avatar" :style="{'--character-color':stickyCharacter.color}"><img v-if="avatar(stickyCharacter)" :src="avatar(stickyCharacter)" alt="" /><i v-else>{{ stickyCharacter.name.slice(0,1) }}</i><b v-if="characterStateStamp(stickyCharacter.id,stickyMessageIndex)" class="avatar-state-stamp">{{ characterStateStamp(stickyCharacter.id,stickyMessageIndex) }}</b></span></div>
		  </Transition>
	  <div v-if="interactionScene" :key="interactionScene.key" class="interaction-scene" :class="[`interaction-scene--${interactionScene.effect}`, `interaction-scene--reaction-${interactionScene.reaction}`, { 'interaction-scene--reverse': interactionScene.reverse, 'interaction-scene--source-only':!interactionScene.target }]" :style="interactionSceneStyle" aria-hidden="true">
		<span class="interaction-character interaction-character--source"><span class="player-avatar"><img v-if="avatar(interactionScene.source)" :src="avatar(interactionScene.source)" alt="" /><i v-else>{{ interactionScene.source.name.slice(0,1) }}</i></span></span>
		<span v-if="!interactionScene.emoji&&(interactionScene.effect==='magic'||interactionScene.effect==='magic-circle')" class="interaction-magic-array"><i></i><i></i><i></i></span>
		<span v-if="interactionScene.effect!=='magic-circle'" class="interaction-projectile" :class="{'interaction-projectile--custom':interactionScene.emoji}"><template v-if="interactionScene.emoji">{{ interactionScene.emoji }}</template><template v-else-if="interactionScene.effect==='throw'">🪨</template><span v-else-if="interactionScene.effect==='heart'" class="interaction-heart-particles">♥</span><span v-else-if="interactionScene.effect==='surprise'" class="interaction-surprise-mark">!</span><span v-else-if="interactionScene.effect==='impact'" class="interaction-impact-burst"></span><span v-else-if="interactionScene.effect==='bullet'" class="interaction-bullet-core"></span><span v-else-if="interactionScene.effect==='magic'" class="interaction-magic-orb"></span><span v-else class="interaction-projectile__sprite"></span></span>
		<span v-if="interactionScene.target" class="interaction-character interaction-character--target"><span class="player-avatar"><img v-if="avatar(interactionScene.target)" :src="avatar(interactionScene.target)" alt="" /><i v-else>{{ interactionScene.target.name.slice(0,1) }}</i></span></span>
		  </div>
		  <div v-for="layer in persistentWeatherLayers" :key="layer.key" class="persistent-weather-layer" :class="`persistent-weather-layer--${layer.effect}`" :style="layer.style" aria-hidden="true"><i v-for="particle in weatherParticles" :key="particle" :style="weatherParticleStyle(particle,layer.effect,layer.speedPercent)"></i></div>
		  <Transition name="toast-pop"><div v-if="toastText" class="player-toast" role="status">{{ toastText }}</div></Transition>
		  <Transition name="playback-complete"><div v-if="completionNotice" class="playback-complete-notice" role="status">播放完成</div></Transition>
	  <Teleport to="body"><Transition name="performance-pop"><div v-if="interactionValidationMessage" class="performance-modal interaction-validation-modal"><section role="alertdialog" aria-modal="true" aria-labelledby="interaction-validation-title"><header><strong id="interaction-validation-title">无法应用头像互动</strong></header><p>{{ interactionValidationMessage }}</p><button type="button" class="primary" autofocus @click="interactionValidationMessage=''">返回选择</button></section></div></Transition></Teleport>
	  <Transition name="coach-fade"><div v-if="playbackCoachOpen" class="playback-coach" @click.stop="dismissPlaybackCoach"><section @click.stop="dismissPlaybackCoach"><span>{{ runtimeAutoplay?'点击画布可以下一句，自动播放状态下也可以哦~':'这个演出没有开启自动播放，请点击画布播放下一句。' }}</span><label @click.stop><input v-model="playbackCoachNeverShow" type="checkbox" />以后不再显示</label><button type="button" class="primary" @click.stop="dismissPlaybackCoach">知道啦</button></section></div></Transition>

      <main ref="playerMain" :style="canvasStyle">
		<div class="player-virtual-list" :style="{height:`${playerVirtualizer.getTotalSize()}px`}">
		<div v-for="{message,index,row} in virtualPlayerEntries" :key="String(row.key)" :ref="measurePlayerRow" class="player-virtual-row" :class="{'player-virtual-row--selected':performanceEditMode&&(performanceSelection.has(message.id)||(performanceTool==='range'&&rangeStartId===message.id))}" :data-index="index" :style="{transform:`translateY(${row.start-playerScrollMargin}px)`}">
		  <article :data-id="message.id" class="player-message" :class="[`player-message--${character(message.characterId)?.position || 'left'}`, `player-message--group-${groupPosition(index)}`, characterStateClass(message.characterId,index), screenEffectMessageId === message.id ? `player-message--effect-${screenEffectActive}` : '', messageTextPulse.messageId===message.id?`player-message--text-${messageTextPulse.animation}`:'', { 'player-message--scripted': performanceEditMode && hasPerformance(message), 'player-message--tool-selected': performanceEditMode && performanceSelection.has(message.id), 'player-message--effect-active': screenEffectMessageId === message.id, 'player-message--revealed': started && index === visibleCount - 1 }]" :style="messageStyle(message)" @click.stop="onMessageClick(message)">
			<div v-if="performanceEditMode && effectRangesAt(message.id).length" class="effect-track-stack" aria-label="持续效果区间"><i v-for="range in effectRangesAt(message.id)" :key="range.track.id" :class="`effect-track--${range.position}`" :style="{'--track-color':effectColorValue(range.track.color)}" :title="persistentEffectLabel(range.track.effect)"><b v-if="range.position==='start'||range.position==='single'">{{ persistentEffectLabel(range.track.effect) }}</b></i></div>
            <span v-if="avatarSlot(message.characterId)" class="player-avatar-slot" :class="{ 'player-avatar-slot--bottom': storyDocument.settings.avatarAlignment === 'bottom' }">
	              <span v-if="showAvatar(message.characterId, index)" class="player-avatar"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><i v-else>{{ character(message.characterId)?.name?.slice(0, 1) || '旁' }}</i><b v-if="characterStateStamp(message.characterId,index)" class="avatar-state-stamp">{{ characterStateStamp(message.characterId,index) }}</b></span>
            </span>
            <div class="player-message__content">
              <small v-if="showOutsideName(message.characterId, index) || storyDocument.settings.showTime">
	                <template v-if="showOutsideName(message.characterId, index)"><span class="character-name" :style="nameStyle(character(message.characterId))">{{ character(message.characterId)?.name }}</span><span v-if="storyDocument.settings.showQqInPreview && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></template>
                <span v-if="storyDocument.settings.showTime" class="message-time">{{ showOutsideName(message.characterId, index) ? ' · ' : '' }}{{ messageTime(message) }}</span>
              </small>
              <div class="bubble" :class="{ 'bubble--narrator-avatar': showNarratorBubbleAvatar(message.characterId, index) }">
				<button v-if="message.replyToId" class="reply-preview" type="button" @click.stop="scrollToVirtualMessage(message.replyToId)"><strong :style="nameStyle(replyCharacter(message.replyToId))">{{ replyCharacter(message.replyToId)?.name || '原消息' }}</strong><span>{{ replySummary(message.replyToId) }}</span></button>
                <div v-if="showNarratorBubbleAvatar(message.characterId, index)" class="narrator-identity"><span class="narrator-avatar"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><i v-else>{{ character(message.characterId)?.name?.slice(0, 1) || '旁' }}</i></span><span v-if="showNarratorName(message.characterId, index)" class="narrator-identity__text"><span class="character-name" :style="nameStyle(character(message.characterId))">{{ character(message.characterId)?.name }}</span><span v-if="storyDocument.settings.showQqInPreview && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></span></div>
				<img v-if="message.kind === 'image' && resourceAvailable(message.asset)" class="story-image" :src="imageUrl(message.asset)" :alt="message.alt || '图片'" @error="markResourceInvalid(message.asset)" @click.stop="openImage(message)" />
				<div v-else-if="message.kind === 'audio'" class="audio-content"><StoryAudioBubble v-if="resourceAvailable(message.asset)" :src="imageUrl(message.asset)" :duration-ms="message.durationMs" :seed="message.id" @error="markResourceInvalid(message.asset)" /><span v-else class="resource-placeholder">【语音】</span><p v-if="message.caption" class="audio-caption">{{ message.caption }}</p></div>
				<span v-else-if="message.kind === 'image'" class="resource-placeholder">【图片】</span>
                <span v-else-if="streamedMessageId === message.id" class="stream-output"><span v-for="token in streamedTokens" :key="token.key" class="stream-token" :class="`stream-token--${tokenAnimation(message)}`">{{ token.text }}</span><i v-if="storyDocument.settings.streamCursor !== 'none'" class="stream-cursor" :class="`stream-cursor--${storyDocument.settings.streamCursor}`"></i></span>
				<span v-else><template v-for="(segment,segmentIndex) in textSegments(renderedText(message))" :key="segmentIndex"><img v-if="segment.faceId" class="inline-cq-face" :src="`/api/editor/cq-face/${segment.faceId}`" :alt="`QQ 表情 ${segment.faceId}`" /><span v-else :class="{'inline-mention':segment.character}" :style="segment.character?nameStyle(segment.character):undefined">{{ segment.text }}</span></template></span>
	              </div>
	              <div v-if="performanceEditMode && visibleEffectLayers(message).length" class="message-layer-summary" aria-label="叠加特效层"><span v-for="layer in visibleEffectLayers(message)" :key="layer.segment.id"><b>第 {{ layer.index+1 }} 层</b>{{ effectSegmentSummary(layer.segment) }}</span></div>
	              <small v-if="performanceEditMode && hasPerformance(message)" class="performance-summary">{{ performanceSummary(message) }}</small>
            </div>
          </article>
		</div>
		</div>

        <article v-if="started && phase === 'typing' && typingCharacter" class="typing-indicator" :class="`typing-indicator--${storyDocument.settings.typingIndicatorEffect}`" :style="{'--character-color':typingCharacter.color}">
          <span class="player-avatar typing-indicator__avatar"><img v-if="avatar(typingCharacter)" :src="avatar(typingCharacter)" alt="" /><i v-else>{{ typingCharacter.name.slice(0, 1) }}</i></span>
