		  <label v-for="token in performanceTokens" :key="token.index"><code :class="{custom:token.custom}">{{ token.text.trim() || '空格' }}</code><n-input-number :value="performanceForm.tokenDelays[token.index]" clearable :min="-30000" :max="30000" :step="25" :show-button="false" :placeholder="`默认约 ${defaultTokenDelay(token)} ms`" @update:value="setTokenDelay(token.index, $event)" /><span>ms</span></label>
