olor=$event" @interaction-speed="performanceForm.interactionSpeedPercent=$event" @preview-interaction="previewFormInteraction"><template #interaction-target><label class="brush-interaction-target"><span>互动目标</span><n-select v-model:value="performanceForm.interactionTargetId" :options="interactionTargetOptions" placeholder="无目标" /></label></template></StoryEffectPicker><footer><span>返回后仍需保存整条消息编排。</span><button type="button" class="primary" @click="performanceEffectPickerOpen=false">完成</button></footer></section></div></Transition></Teleport>

