<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, toRaw, watch } from "vue";
import { useThemeDark } from "~/composables/useTheme";
import { themeModeOptions, useThemeMode } from "~/composables/useTheme";
import { useVirtualizer } from "@tanstack/vue-virtual";
import { zipSync } from "fflate";
import { toBlob } from "html-to-image";
import DeferredSettingSlider from "./DeferredSettingSlider.vue";
import StoryAudioBubble from "./StoryAudioBubble.vue";
import StoryImageViewer from "./StoryImageViewer.vue";
import StoryEffectPicker from "./StoryEffectPicker.vue";
import { storyAvatarUrl } from "~/story/avatar";
import { isStoryMessageFiltered } from "~/story/message-filter";
import { createStoryId, playbackDelay, segmentStoryText, storyDisplayText, storyMessageGroupPosition, storyStreamingText, storyTextSegments } from "~/story/model";
import { clearLegacyMessageEffects, effectSegmentDuration, INTERACTION_DEFAULT_REACTION, MAX_MESSAGE_EFFECT_SEGMENTS, messageEffectSegments } from "~/story/message-effects";
import { readableRoleColor, storyPalette } from "~/story/palette";
import { markOnboardingSeen, onboardingSeen } from "~/story/onboarding";
import { vfxAssets } from "~/story/vfx-assets";
import type { StoryArchive, StoryAssetRef, StoryCharacter, StoryCharacterState, StoryEffectColor, StoryInteractionEffect, StoryInteractionReaction, StoryMessage, StoryMessageEffectSegment, StoryPersistentEffect, StoryScreenEffect, StorySettings, StoryStreamTokenAnimation } from "~/story/types";

