@keyframes persistent-rain{to{background-position:22px 80px,-31px 120px,80px 150px}}@keyframes persistent-snow{to{background-position:20px 140px,-18px 210px}}@keyframes persistent-water{50%{background-position:0 12px,20px -8px}}@keyframes persistent-grain{25%{transform:translate(2%,-1%)}50%{transform:translate(-1%,2%)}75%{transform:translate(1%,1%)}}

